int main() {
    const int solicitadas = 6;
    const int disponibles = 4;
    const bool permiso = true;
    if ((solicitadas < 1) || (solicitadas > 12)) {
        std::cout << "Quantité invalide";
    } else if (!permiso) {
        std::cout << "Sans autorisation";
    } else if (solicitadas <= disponibles) {
        std::cout << "Complet";
    } else {
        const int faltantes = solicitadas - disponibles;
        std::cout << "En attente : " << faltantes;
    }
    return 0;
}

