#include <iostream>

int main() {
    const int disponibles = 11;
    int usados = 3;
    const int antes = usados;
    usados = usados + 4;
    const int libres = disponibles - usados;
    const bool queda_espacio = libres > 0;
    if (queda_espacio) {
        std::cout << "Libres : " << libres << "\n";
    } else {
        std::cout << "Complet\n";
    }
    std::cout << "Avant : " << antes;
    return 0;
}

